"""Build the static informational pages; no runtime build step is required."""

from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
PAGES = {
    "about": (
        "From chat chaos to coordinated rescue.",
        """<p class="lead">A volunteer dispatch co-pilot with a human in the loop. Multilingual messages become structured needs and offers, repeats are grouped, and nearby resources are suggested for coordinator approval.</p>
<h2>Why coordination matters</h2><p>During the December 2023 Chennai floods, residents reported unanswered or busy civic helplines. Volunteers carried out rescues in low-lying areas. <a href="https://www.thenewsminute.com/amp/story/tamil-nadu/chennai-floods-helplines-inundated-people-struggle-to-contact-authorities">The News Minute</a> and <a href="https://www.dtnext.in/news/city/calls-to-govt-helplines-go-unanswered-754073">DT Next</a> describe the difficulty of reaching assistance.</p>
<p>A volunteer account describes at least a thousand daily requests and reviewing over 50,000 requests, including repeats. <a href="https://www.dtnext.in/volunteer-diaries-we-had-calls-regarding-pregnant-women-being-stranded">Read the volunteer account</a>. Another account describes miscommunication and redirected resources despite coordination groups: <a href="https://www.dtnext.in/news/city/volunteers-the-undying-spirit-of-chennai-soars-on-social-media-753635">DT Next on volunteer coordination</a>.</p>
<p>During the October–November 2024 Valencia floods, volunteers organised through social platforms, including a Telegram channel with more than 14,000 members. Reports describe disorganised official coordination and a fake emergency number circulating. <a href="https://www.izquierdadiario.es/Desborde-de-solidaridad-ante-la-inaccion-del-Gobierno-miles-de-voluntarios-autoorganizados-se">Volunteer organising</a>, <a href="https://inspain.news/?p=40691">coordination difficulties</a>, <a href="https://thestar.com.my/tech/tech-news/2024/11/08/online-disinformation-exacerbates-spain-flood-disaster">misinformation reporting</a>.</p>
<p>Volunteer helplines are a practical starting point: <a href="https://citizenmatters.in/citizen-monsoon-helpline-in-tambaram/">Citizen Matters describes Tambaram’s helpline</a>, staffed by about 70 volunteers across five zones.</p>
<h2>One loop, human judgment throughout</h2><article><ol><li>Post a concrete need or offer in Telegram, or try a simulated message.</li><li>The desk extracts the resource, approximate area, urgency and confidence.</li><li>It groups repeat reports and suggests compatible resources nearby.</li><li>A coordinator reviews the exact notification and approves a connection.</li><li>Only then does the bot notify the originating chat.</li></ol></article>
<h2>Honest limits</h2><p>This is a hackathon prototype, not an emergency service. Telegram intake only; no WhatsApp group reading or live call handling. Extraction can be wrong. Fallback summaries retain the original wording and do not translate it. Demo participants and drill messages are simulated. We have no official emergency-service integration or verified volunteer network.</p>""",
    ),
    "architecture": (
        "A small system. A deliberate human checkpoint.",
        """<p class="lead">One FastAPI process serves the desk, API, queue workers and Telegram long polling. SQLite holds durable intake, suggestions and the audit trail.</p><img class="architecture-img" src="/static/img/architecture.svg" alt="Telegram and simulated intake enter a durable queue, then extraction, location lookup and triage, then match suggestions, human approval and Telegram notification."><h2>From message to decision</h2><article><p><strong>Intake:</strong> Telegram updates and the protected intake endpoint persist messages before processing. Duplicate Telegram delivery is idempotent; unfinished queued intake is restored on restart.</p><p><strong>Understanding:</strong> A configurable Chat Completions service extracts validated fields. Timeouts and provider errors fall back to visibly labelled rules. Gazetteer lookup works without network access; remote geocoding is opt-in and cached.</p><p><strong>Coordination:</strong> Same-sender repeats are grouped. Different senders stay separate. Compatible items within the configured radius become suggestions, with score breakdowns.</p><p><strong>Human approval:</strong> A transaction prevents two coordinators from allocating the same card. Approval reserves the pair and rejects conflicting suggestions. Notifications have a visible delivery state and an explicit retry on failure.</p></article><h2>Private by design</h2><p>Public lists receive redacted text and coordinates placed within an approximate grid cell. Exact coordinates and raw source text are available only in authenticated coordinator details. Simulation never posts into Telegram.</p><h2>Where it runs</h2><p>Vultr Ubuntu Compute → Caddy HTTPS → non-root Python container → persistent SQLite volume. Use a single Uvicorn worker. Higher traffic requires a shared queue, transactional server database and distributed limits before adding workers.</p>""",
    ),
    "eval": (
        "Measure what the extractor actually does.",
        """<p class="lead">A reproducible synthetic smoke benchmark, with the extractor used on every sample. These template-based checks do not establish real-world rescue accuracy.</p><div id="evaluation-report"><p>Loading the latest evaluation…</p></div><h2>Reproduce the report</h2><pre>python scripts/eval.py</pre><p>Checks include intent, category, canonical resource, location extraction, urgency within one level, and misinformation detection. The report includes all expected and actual fields. No crowdsourced or real emergency messages are used.</p>""",
    ),
    "join": (
        "Put coordination to the test.",
        """<p class="lead">Try a safe, fictional storm drill. Send needs and offers in your language, review the resulting cards, and help identify mistakes before any real use.</p><div class="reach"><div><strong id="participants">—</strong><span>participants (includes simulated)</span></div><div><strong id="countries">—</strong><span>countries, self-reported</span></div></div><article id="join-links"><p>Loading Telegram configuration…</p></article><h2>Copy a sample message</h2><div id="samples"></div><h2>Take part responsibly</h2><ol><li>Use fictional situations and broad locality names. Do not post personal contact details or real emergencies.</li><li>Send a need, then a compatible offer from a different participant. Check that the desk suggests a connection.</li><li>Ask the coordinator to review and approve it. An open simulation approval never sends a real Telegram notification.</li><li>Optionally send <code>/iam India</code> (or your country) to contribute a self-reported country count.</li><li>Send <code>/forget</code> to delete your stored app records after testing.</li></ol><p>These counts are participation records, not verified people or countries. No claim of real adoption is made.</p>""",
    ),
    "safety": (
        "Useful coordination starts with care.",
        """<p class="lead">ReliefSync Desk is not an emergency service. Contact local emergency services first when someone is in immediate danger.</p><h2>What is stored</h2><p>Message text, private Telegram routing identifiers, structured cards, timestamps, approximate public locations, exact private locations if supplied, and an audit trail. Sender identifiers used for grouping are salted hashes. Optional country information is self-reported. Raw text may be sent to the extraction provider when one is configured. Remote geocoding is disabled by default.</p><h2>What visitors can see</h2><p>Contact details are redacted using rules. Coordinates are snapped to an approximate grid with a deterministic offset. Exact coordinates and raw text require coordinator login. Automated redaction is imperfect: use broad locality names and keep sensitive details out of group posts.</p><h2>Control your records</h2><p>Send <code>/forget</code> to the Telegram bot. Your app messages, cards and participation row are deleted and related matches rejected. This cannot erase messages already posted in Telegram or copies held by external providers. Demo reset deletes simulated records only. Operators control backup retention and must delete expired backup copies themselves.</p><h2>A person approves every connection</h2><p>Extraction confidence is an estimate, not a guarantee. Volunteers and availability are not verified. Coordinators should verify both sides before approval and avoid sending children or vulnerable people to unknown contacts. Misinformation cards are blocked from matching.</p><h2>Remaining risks</h2><p>We do not provide identity checks, background checks, end-to-end encryption of the database, medical decisions, verified availability, guaranteed message delivery or protection from determined adversaries. Shared coordinator credentials are intended for a small controlled demo, not a large public emergency operation.</p>""",
    ),
}


def main() -> None:
    for slug, (title, content) in PAGES.items():
        html = f"""<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{slug.title()} · ReliefSync Desk</title><link rel="icon" href="/static/img/favicon.svg"><link rel="stylesheet" href="/static/css/tokens.css"><link rel="stylesheet" href="/static/css/app.css"><script type="module" src="/static/js/pages.js"></script></head><body><a class="skip" href="#main">Skip to content</a><div id="shared-header"></div><main id="main" class="prose"><nav aria-label="Page navigation"><a href="/">Desk</a> · <a href="/about">About</a> · <a href="/architecture">System</a> · <a href="/join">Join</a> · <a href="/eval">Evaluation</a> · <a href="/safety">Safety</a></nav><p class="eyebrow">RELIEFSYNC DESK / {slug.upper()}</p><h1>{title}</h1>{content}</main><div id="shared-footer"></div><div id="toast" class="toast" role="status" hidden></div></body></html>"""
        (ROOT / "static" / f"{slug}.html").write_text(html, encoding="utf-8")
    svg = """<svg xmlns="http://www.w3.org/2000/svg" width="960" height="440" viewBox="0 0 960 440"><rect width="960" height="440" rx="16" fill="#f0f6f7"/><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10" fill="#0e7c86"/></marker></defs><g stroke="#0e7c86" stroke-width="2" fill="none" marker-end="url(#arrow)"><path d="M270 100H350"/><path d="M610 100H690"/><path d="M810 150V275"/><path d="M690 325H610"/><path d="M350 325H270"/></g>"""
    for x, y, title, sub in [
        (30, 50, "01 / INTAKE", "Telegram · simulated messages"),
        (350, 50, "02 / UNDERSTAND", "Validated extraction · geocoding"),
        (690, 50, "03 / TRIAGE", "Dedupe · urgency · match score"),
        (690, 275, "04 / SUGGEST", "Compatible resources nearby"),
        (350, 275, "05 / HUMAN APPROVAL", "Review · confirm · audit"),
        (30, 275, "06 / CONNECT", "Telegram notification · follow-up"),
    ]:
        svg += f'<rect x="{x}" y="{y}" width="240" height="100" rx="12" fill="white" stroke="#cbdde0"/><text x="{x + 18}" y="{y + 38}" fill="#0e7c86" font-family="sans-serif" font-size="14" font-weight="bold">{title}</text><text x="{x + 18}" y="{y + 65}" fill="#526578" font-family="sans-serif" font-size="12">{sub}</text>'
    svg += '<text x="480" y="218" text-anchor="middle" fill="#526578" font-family="sans-serif" font-size="13">SQLite WAL · persistent intake · public-safe API · live SSE updates</text></svg>'
    (ROOT / "static/img/architecture.svg").write_text(svg, encoding="utf-8")
    (ROOT / "docs").mkdir(exist_ok=True)
    (ROOT / "docs/architecture.svg").write_text(svg, encoding="utf-8")


if __name__ == "__main__":
    main()
